output_text:
[
  {
    "id": "take_cart_at_bay",
    "text": "On entering the store, the shopper is obliged to take the waiting cart from the cart bay before proceeding with the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_bay": "at(1,5)",
        "cart_waiting_at_bay": "cartAt(1,5)"
      },
      "events": {
        "cart_taken_from_bay": {
          "pre": {
            "and": [
              "at_cart_bay",
              "cart_waiting_at_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cart_taken_from_bay"
    }
  },
  {
    "id": "no_enter_without_cart",
    "text": "It is prohibited to enter the shopping aisles from the cart bay unless the shopper already has a cart.",
    "abstraction": {
      "state_properties": {
        "at_cart_bay": "at(1,5)",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "entering_aisles_from_bay": {
          "pre": {
            "and": [
              "at_cart_bay",
              {
                "or": [
                  "N",
                  "E"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "without_cart",
          "entering_aisles_from_bay"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Items should not be carried by hand; shoppers must avoid ever being in a hand-full state.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_taking_items",
    "text": "After taking any required item while using a cart, the shopper is obliged to return or park the cart at the service counter.",
    "abstraction": {
      "state_properties": {
        "at_service_counter": "at(0,1)"
      },
      "events": {
        "item_taken_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "cart_returned_to_counter": {
          "pre": {
            "and": [
              "at_service_counter",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_taken_with_cart",
      "discharge": "cart_returned_to_counter"
    }
  },
  {
    "id": "unattended_cart_only_at_parking_spots",
    "text": "An unattended cart may only be stationed at an approved parking spot: the initial cart bay or the service counter.",
    "abstraction": {
      "state_properties": {
        "cart_unattended": {
          "not": "hasCart"
        },
        "cart_at_approved_spot": {
          "or": [
            "cartAt(1,5)",
            "cartAt(0,1)"
          ]
        },
        "cart_unattended_in_wrong_place": {
          "and": [
            "cart_unattended",
            {
              "not": "cart_at_approved_spot"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_unattended_in_wrong_place"
    }
  },
  {
    "id": "leave_cart_only_at_counter",
    "text": "Putting down a cart is prohibited anywhere except at the service counter cell.",
    "abstraction": {
      "state_properties": {
        "at_service_counter": "at(0,1)",
        "not_at_service_counter": {
          "not": "at_service_counter"
        }
      },
      "events": {
        "cart_left": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_left",
          "not_at_service_counter"
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "The shopper may exit only after the cart has been left at the service counter and the shopper is no longer holding the cart.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_counter": "cartAt(0,1)",
        "without_cart": {
          "not": "hasCart"
        },
        "ready_to_exit": {
          "and": [
            "cart_parked_at_counter",
            "without_cart"
          ]
        }
      },
      "events": {
        "exit_attempt": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_attempt",
          {
            "not": "ready_to_exit"
          }
        ]
      }
    }
  }
]
